(async()=>{
  'use strict';
  const A=globalThis.DraftmangoAccounts;if(!await A.protect())return;
  const W=globalThis.DraftmangoWorkspace,{e,icon}=W;await W.init();
  const main=document.querySelector('#main'),sidebar=document.querySelector('#sidebar'),scrim=document.querySelector('#sidebar-scrim');
  let references=[],notes='',build={level:'standard',starter:W.preferences.starter,color:W.preferences.color},current='home',projectFilter='',projectSort='updated',projectScope='active';
  const date=value=>new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
  function closeNav(){sidebar.classList.remove('is-open');scrim.hidden=true;document.querySelector('#open-sidebar').setAttribute('aria-expanded','false');if(innerWidth<=760)sidebar.inert=true;}
  document.querySelector('#open-sidebar').onclick=()=>{sidebar.inert=false;sidebar.classList.add('is-open');scrim.hidden=false;document.querySelector('#open-sidebar').setAttribute('aria-expanded','true');sidebar.querySelector('.ws-nav-close').focus();};scrim.onclick=closeNav;
  document.querySelector('#mobile-build-settings').onclick=()=>W.buildSettings(null,next=>build=next);document.addEventListener('keydown',event=>{if(event.key==='Escape')closeNav();});window.addEventListener('resize',()=>{if(innerWidth>760){sidebar.inert=false;closeNav();}else if(!sidebar.classList.contains('is-open'))sidebar.inert=true;});
  function nav(){W.sidebar(sidebar,current);sidebar.querySelector('.ws-nav-close').onclick=closeNav;if(innerWidth<=760&&!sidebar.classList.contains('is-open'))sidebar.inert=true;}
  function header(title,copy,actions='',eyebrow=''){return `<header class="ws-page-header"><div>${eyebrow?`<p class="ws-eyebrow">${eyebrow}</p>`:''}<h1>${title}</h1><p>${copy}</p></div>${actions}</header>`;}
  function list(items,kind='project'){return `<div class="ws-record-list">${items.map(p=>`<article class="ws-record-row"><a class="ws-record-open" href="${kind==='chat'?W.href(p):'#project/'+p.id}">${icon(kind==='chat'?'chat':'folder')}<span><strong>${e(p.title)}${W.meta(p).pinned?' <span class="ws-badge">Pinned</span>':''}</strong><small>${kind==='chat'?(W.meta(p).parentId?e(W.get(W.meta(p).parentId)?.title||'Project'):'Standalone chat'):e(W.meta(p).brief?.slice(0,110)||'Private project')} · ${date(p.updatedAt)}</small></span></a><button class="icon-button" data-menu="${e(p.id)}" aria-label="Manage ${kind} ${e(p.title)}">${icon('more')}</button></article>`).join('')}</div>`;}
  function wireMenus(){main.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>W.recordMenu(b,W.get(b.dataset.menu)));}
  const empty=(title,copy,action='')=>`<div class="ws-empty">${icon('folder')}<h2>${title}</h2><p>${copy}</p>${action}</div>`;
  function home(){
    main.className='ws-home';main.innerHTML=`<section class="ws-create"><h1>What would you like to build?</h1><p>From a first idea to your next release.</p><form id="idea-form" class="ws-composer"><label class="sr-only" for="idea-input">Describe what you would like to build</label><textarea id="idea-input" rows="3" maxlength="12000" placeholder="Describe a website, app, or feature you want to build…" required></textarea><div id="reference-chips" class="ws-reference-chips"></div><div class="ws-composer-tools"><button type="button" id="add-context" class="text-button" aria-label="Add files, images or GitHub"><span class="ws-plus">${icon('plus')}</span><span>Attach context</span></button><div><button type="button" id="build-settings" class="text-button" aria-label="Toggle build settings">${icon('sliders')}<span>Build settings</span></button><button type="submit" class="ws-send" aria-label="Send build request" disabled>${icon('up')}</button></div></div></form><p class="keyboard-hint">Enter to send <span>·</span> Shift + Enter for a new line</p></section><section class="ws-recent-projects"><div class="ws-section-heading"><div><h2>Recent projects</h2><p>Continue where you left off.</p></div><a class="text-link" href="#projects">View all ${icon('arrow')}</a></div><div id="home-recents"></div></section>`;
    const field=main.querySelector('#idea-input'),form=main.querySelector('#idea-form');field.value=sessionStorage.getItem('draftmango-prompt:'+A.user.id)||'';const refresh=()=>{form.querySelector('[type=submit]').disabled=!field.value.trim();sessionStorage.setItem('draftmango-prompt:'+A.user.id,field.value);};refresh();field.oninput=refresh;field.onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();if(field.value.trim())form.requestSubmit();}};
    main.querySelector('#add-context').onclick=event=>W.attachmentMenu(event.currentTarget,async files=>{try{references=await W.references(files,references);chips();}catch(error){W.toast(error.message);}},()=>W.dialog('Project notes',`<label for="context-notes">Context for your request</label><textarea id="context-notes" rows="6" maxlength="6000">${e(notes)}</textarea>`,{submit:d=>{notes=d.querySelector('textarea').value;chips();}}));main.querySelector('#build-settings').onclick=()=>W.buildSettings(null,next=>build=next);
    function chips(){main.querySelector('#reference-chips').innerHTML=references.map((r,i)=>`<span>${icon(r.type.startsWith('image')?'monitor':'file')}${e(r.name)}<button type="button" data-remove-reference="${i}" aria-label="Remove ${e(r.name)}">×</button></span>`).join('')+(notes?'<span>Project notes <button type="button" id="remove-notes" aria-label="Remove project notes">×</button></span>':'');main.querySelectorAll('[data-remove-reference]').forEach(b=>b.onclick=()=>{references.splice(Number(b.dataset.removeReference),1);chips();});if(main.querySelector('#remove-notes'))main.querySelector('#remove-notes').onclick=()=>{notes='';chips();};}chips();
    form.onsubmit=event=>{event.preventDefault();const prompt=field.value.trim();if(!prompt)return;const p=W.create('chat',prompt.slice(0,60),prompt.slice(0,1200));p.workspace={...p.workspace,queuedPrompt:prompt,attachments:references,notes,build};p.creationPreferences=notes?[notes.slice(0,600)]:[];p.messages=[{role:'user',text:prompt.slice(0,3000)}];p.ai={state:'pending'};W.save(p);sessionStorage.removeItem('draftmango-prompt:'+A.user.id);location.href=W.href(p);};homeRecents();
  }
  function homeRecents(){const root=main.querySelector('#home-recents');if(!root)return;const items=W.records('project').slice(0,3);root.innerHTML=items.length?list(items):empty('Your next project starts here','Create a project to organise files and related chats.','<button class="button" id="create-first-project">Create project</button>');main.querySelector('#create-first-project')?.addEventListener('click',()=>W.newProject());wireMenus();}
  function chats(){main.className='ws-page ws-chats-page';main.innerHTML=header('Chats','Conversations on their own, or within a project.','<a class="button" href="#new">'+icon('plus')+'New chat</a>')+`<div class="ws-collection-tools"><label class="ws-search">${icon('search')}<input type="search" id="chat-search" placeholder="Search chats" aria-label="Search chats"></label><select id="chat-scope" aria-label="Chat filter"><option value="active">All chats</option><option value="standalone">Standalone chats</option><option value="archived">Archived chats</option></select></div><div id="chat-list"></div>`;const paint=()=>{const query=main.querySelector('#chat-search').value.toLowerCase(),scope=main.querySelector('#chat-scope').value;const rows=W.records('chat',scope==='archived').filter(p=>p.title.toLowerCase().includes(query)&&(scope!=='standalone'||!W.meta(p).parentId));main.querySelector('#chat-list').innerHTML=rows.length?list(rows,'chat'):empty('No chats here yet','Start a new conversation or adjust your search.');wireMenus();};main.querySelector('#chat-search').oninput=paint;main.querySelector('#chat-scope').onchange=paint;paint();}
  function projects(){main.className='ws-page';main.innerHTML=header('Your projects','Create something new, or continue where you left off.','<button class="button primary" id="create-project">'+icon('plus')+'Create project</button>','YOUR DEVELOPMENT SPACE')+`<div class="ws-collection-tools"><label class="ws-search">${icon('search')}<input type="search" id="project-search" placeholder="Search projects" aria-label="Search projects" value="${e(projectFilter)}"></label><select id="project-sort" aria-label="Sort projects"><option value="updated">Recently updated</option><option value="created">Recently created</option><option value="name">Name A–Z</option></select><select id="project-scope" aria-label="Project filter"><option value="active">All projects</option><option value="pinned">Pinned projects</option><option value="archived">Archived projects</option></select></div><p class="muted" id="results-count"></p><div id="all-projects"></div><p class="ws-footnote">Projects are private to your account.</p>`;main.querySelector('#create-project').onclick=()=>W.newProject();main.querySelector('#project-sort').value=projectSort;main.querySelector('#project-scope').value=projectScope;
    function paint(){projectFilter=main.querySelector('#project-search').value;projectSort=main.querySelector('#project-sort').value;projectScope=main.querySelector('#project-scope').value;const items=W.records('project',projectScope==='archived').filter(p=>p.title.toLowerCase().includes(projectFilter.toLowerCase())&&(projectScope!=='pinned'||W.meta(p).pinned));items.sort((a,b)=>projectSort==='name'?a.title.localeCompare(b.title):projectSort==='created'?b.createdAt.localeCompare(a.createdAt):b.updatedAt.localeCompare(a.updatedAt));main.querySelector('#results-count').textContent=items.length+' project'+(items.length===1?'':'s');main.querySelector('#all-projects').innerHTML=items.length?list(items):empty(projectFilter?'No projects found':'Your next project starts here',projectFilter?'Try a different search.':'Create a project with a name and an optional brief. Come back anytime to continue.','<button class="button" id="create-empty-project">Create project</button>');main.querySelector('#create-empty-project')?.addEventListener('click',()=>W.newProject());wireMenus();}main.querySelector('#project-search').oninput=paint;main.querySelector('#project-sort').onchange=paint;main.querySelector('#project-scope').onchange=paint;paint();
  }
  function project(id,tab='chats'){
    const p=W.get(id);if(!p){main.className='ws-page';main.innerHTML=empty('Project unavailable','Return to your projects to choose another.','<a class="button" href="#projects">Your projects</a>');return;}
    main.className='ws-page';main.innerHTML=`<a class="text-link" href="#projects">${icon('folder')}Your projects</a>`+header(e(p.title),e(W.meta(p).brief||'A space for your source files and related conversations.'),`<div class="ws-action-row"><a class="button primary" href="${W.href(p)}">Open editor ${icon('external')}</a><button class="icon-button" id="project-options" aria-label="Manage project">${icon('more')}</button></div>`)+`<nav class="settings-tabs" aria-label="Project sections">${['chats','files','instructions','activity'].map(t=>`<a href="#project/${e(id)}/${t}" ${tab===t?'aria-current="page"':''}>${t[0].toUpperCase()+t.slice(1)}</a>`).join('')}</nav><div id="project-content"></div>`;main.querySelector('#project-options').onclick=event=>W.recordMenu(event.currentTarget,p);const area=main.querySelector('#project-content');
    if(tab==='files'){const files=p.codeDraft||p.files||{};area.innerHTML=`<div class="ws-section-heading"><h2>Source files</h2><a class="button" href="${W.href(p)}&view=code">Open file explorer</a></div>`+Object.keys(files).map(name=>`<a class="ws-file-row" href="${W.href(p)}&view=code&file=${encodeURIComponent(name)}">${icon('file')}<strong>${e(name)}</strong><span>${new TextEncoder().encode(files[name]).length.toLocaleString()} bytes</span>${icon('external')}</a>`).join('');}
    else if(tab==='instructions'){area.innerHTML=`<section class="settings-card"><h2>Project instructions</h2><p>Context shared with every new chat in this project.</p><form id="instructions-form"><label for="project-brief">Project brief</label><textarea id="project-brief" rows="3" maxlength="3000">${e(W.meta(p).brief||'')}</textarea><label for="project-instructions">Instructions</label><textarea id="project-instructions" rows="7" maxlength="6000" placeholder="Describe conventions, requirements, and what the agent should know…">${e(W.meta(p).instructions||'')}</textarea><div class="card-actions"><span>Saved to this project.</span><button class="button primary">Save instructions</button></div></form></section>`;area.querySelector('form').onsubmit=event=>{event.preventDefault();W.update(id,{workspace:{brief:area.querySelector('#project-brief').value,instructions:area.querySelector('#project-instructions').value}});W.toast('Project instructions saved.');};}
    else if(tab==='activity'){area.innerHTML='<p>Loading project activity…</p>';W.loadActivity().then(items=>{if(!document.contains(area))return;const related=new Set([p.id,...W.records('chat').filter(c=>W.meta(c).parentId===p.id).map(c=>c.id)]);const rows=items.filter(x=>related.has(x.projectId));area.innerHTML=rows.length?rows.map(x=>`<div class="ws-setting-row"><strong>${e(x.kind)} ${x.success?'completed':'failed'}</strong><span>${e(new Date(x.at).toLocaleString())}</span></div>`).join(''):empty('No activity yet','Run a preview or start a chat in this project.');}).catch(error=>area.textContent=error.message);}
    else{const related=W.records('chat').filter(c=>W.meta(c).parentId===id);area.innerHTML=`<div class="ws-section-heading"><div><h2>Chats</h2><p>Conversations in this project share its source files and instructions.</p></div><button class="button" id="project-new-chat">${icon('plus')}New chat</button></div>`+(related.length?list(related,'chat'):empty('Start a conversation','Describe what you would like to build or change.'));area.querySelector('#project-new-chat').onclick=()=>{const chat=W.create('chat','New chat','',id);location.href=W.href(chat);};wireMenus();}
  }
  function cli(){main.className='ws-page';main.innerHTML=header('CLI tasks','Follow the work happening in your terminal and review its proposed changes.','<a class="button" href="#settings/cli">CLI devices</a>','LOCAL DEVELOPMENT')+`<div class="ws-cli-layout"><section class="settings-card"><h2>Recent tasks</h2><p>No local tasks yet.</p><p class="muted">CLI pairing is postponed. When it is available, your local tasks will appear here.</p></section><section class="ws-empty"><h2>Your terminal, connected.</h2><p>Select a task to see progress, questions, local checks, and proposed source changes.</p></section></div>`;}
  function device(){main.className='ws-page';main.innerHTML=`<section class="ws-device"><h1>Connect your terminal</h1><p>Signed in as ${e(A.user.email)}</p><p>Match this code with the terminal where you started device pairing.</p><form id="device-form">${W.field('Terminal code','terminal-code','','text','required maxlength="20" placeholder="XXXX-XXXX"')}<button class="button primary">Look up code</button><p id="device-status" role="status"></p></form><a href="#home" class="text-link">Back to workspace</a></section>`;main.querySelector('form').onsubmit=event=>{event.preventDefault();main.querySelector('#device-status').textContent='CLI device pairing is not available yet. No terminal has been authorized.';};}
  function route(){globalThis.DraftmangoDomains?.dispose();W.closeMenu();const [page,arg,tab]=location.hash.slice(1).split('/');current=['projects','chats','project','settings','domains','cli','device'].includes(page)?page:'home';nav();closeNav();document.title=({home:'Workspace',project:'Project',projects:'Your projects',chats:'Chats',settings:'Settings',domains:'Domains',cli:'CLI tasks',device:'Connect terminal'})[current]+' — Draftmango';if(current==='home'){home();if(page==='new'){main.querySelector('#idea-input').value='';main.querySelector('#idea-input').dispatchEvent(new Event('input'));main.querySelector('#idea-input').focus();}if(page==='new-project')W.newProject();}else if(current==='projects')projects();else if(current==='chats')chats();else if(current==='project')project(arg,tab);else if(current==='settings'){main.className='ws-page';globalThis.DraftmangoSettings.render(main,arg);}else if(current==='domains'){main.className='ws-page';main.innerHTML='<section id="page-domains" class="domains-page"></section>';globalThis.DraftmangoDomains.mount({...W.library(),projects:W.records('project')});}else if(current==='cli')cli();else device();window.scrollTo(0,0);}
  window.addEventListener('hashchange',route);window.addEventListener('draftmango:records',()=>{nav();if(current==='home')homeRecents();else if(current==='projects')projects();else if(current==='chats')chats();else if(current==='project'){const [,id,tab]=location.hash.slice(1).split('/');project(id,tab);}});window.addEventListener('storage',event=>{if(event.key===A.key('projects')){nav();if(current==='home')homeRecents();}});route();A.paint();
})();
